import{_ as t,o,c,a4 as n}from"./chunks/framework.3hqjI0F0.js";const u=JSON.parse('{"title":"Tài Liệu Nghiên Cứu (R&D): Gọi Thoại/Video 2 Chiều (ZRTC), Tương Thích React Native & Cơ Chế Dữ Liệu Nhóm (@softtynet/zca-js v2.3.0)","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://softtyos.github.io/zca-js-docs/RND_REACT_NATIVE_AND_VOICE_VIDEO_CALL.html"}],["meta",{"property":"og:url","content":"https://softtyos.github.io/zca-js-docs/RND_REACT_NATIVE_AND_VOICE_VIDEO_CALL.html"}],["meta",{"property":"og:title","content":"Tài Liệu Nghiên Cứu (R&D): Gọi Thoại/Video 2 Chiều (ZRTC), Tương Thích React Native & Cơ Chế Dữ Liệu Nhóm (@softtynet/zca-js v2.3.0)"}],["meta",{"property":"og:description","content":"Bộ SDK Zalo API Hiện Đại Cho Node.js, TypeScript & Bun bởi Softtynet Co., Ltd."}]]},"headers":[],"relativePath":"RND_REACT_NATIVE_AND_VOICE_VIDEO_CALL.md","filePath":"RND_REACT_NATIVE_AND_VOICE_VIDEO_CALL.md","lastUpdated":1793200976000}'),i={name:"RND_REACT_NATIVE_AND_VOICE_VIDEO_CALL.md"};function d(a,e,l,r,h,s){return o(),c("div",null,[...e[0]||(e[0]=[n('<h1 id="tai-lieu-nghien-cuu-r-d-goi-thoai-video-2-chieu-zrtc-tuong-thich-react-native-co-che-du-lieu-nhom-softtynet-zca-js-v2-3-0" tabindex="-1">Tài Liệu Nghiên Cứu (R&amp;D): Gọi Thoại/Video 2 Chiều (<code>ZRTC</code>), Tương Thích React Native &amp; Cơ Chế Dữ Liệu Nhóm (<code>@softtynet/zca-js</code> v2.3.0) <a class="header-anchor" href="#tai-lieu-nghien-cuu-r-d-goi-thoai-video-2-chieu-zrtc-tuong-thich-react-native-co-che-du-lieu-nhom-softtynet-zca-js-v2-3-0" aria-label="Permalink to &quot;Tài Liệu Nghiên Cứu (R&amp;D): Gọi Thoại/Video 2 Chiều (`ZRTC`), Tương Thích React Native &amp; Cơ Chế Dữ Liệu Nhóm (`@softtynet/zca-js` v2.3.0)&quot;">​</a></h1><blockquote><p><strong>Tài liệu lưu hành nội bộ (Internal R&amp;D Documentation)</strong>: Lưu trữ trong thư mục <code>docs/</code> (đã được loại trừ khỏi gói phát hành NPM qua <code>.npmignore</code> và <code>package.json#files</code>) để phục vụ việc tra cứu, phân tích sâu và nâng cấp kiến trúc trong các giai đoạn tiếp theo.</p></blockquote><hr><h2 id="_1-chuyen-đe-1-kien-truc-goi-thoai-video-voicecall-signaling-vs-zrtc-media-engine" tabindex="-1">1. Chuyên đề 1: Kiến trúc Gọi Thoại &amp; Video (<code>VoiceCall Signaling</code> vs <code>ZRTC Media Engine</code>) <a class="header-anchor" href="#_1-chuyen-đe-1-kien-truc-goi-thoai-video-voicecall-signaling-vs-zrtc-media-engine" aria-label="Permalink to &quot;1. Chuyên đề 1: Kiến trúc Gọi Thoại &amp; Video (`VoiceCall Signaling` vs `ZRTC Media Engine`)&quot;">​</a></h2><h3 id="_1-1-tach-biet-2-tang-trong-mot-cuoc-goi-zalo" tabindex="-1">1.1. Tách biệt 2 tầng trong một cuộc gọi Zalo <a class="header-anchor" href="#_1-1-tach-biet-2-tang-trong-mot-cuoc-goi-zalo" aria-label="Permalink to &quot;1.1. Tách biệt 2 tầng trong một cuộc gọi Zalo&quot;">​</a></h3><p>Một cuộc gọi Thoại (<code>CallType.Audio = 1</code>) hoặc Video (<code>CallType.Video = 3</code>) trên Zalo PC (<code>26.7.10</code>) được chia thành <strong>2 tầng hoàn toàn độc lập</strong>:</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    subgraph T1[&quot;Tầng 1: Luồng Báo Hiệu (Signaling Plane - 30 API trong api.call)&quot;]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        S1[&quot;api.call.sendVoiceCall(calleeId, { callType })&quot;] --&gt; S2[&quot;Bước 1: GET /api/voicecall/requestcall (cmd 11300, zpw_type=24)&quot;]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        S2 --&gt; S3[&quot;Nhận thông tin phòng gọi: sessId, rtpServer, rtcpServer, zrtpKey, codec&quot;]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        S3 --&gt; S4[&quot;Bước 2: GET /api/voicecall/request (cmd 11301, subCommand=3, extendData)&quot;]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        S4 --&gt; S5[&quot;Máy người nhận đổ chuông thật (Audio / Video)&quot;]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        S5 --&gt; S6[&quot;WebSocket (cmd 601 &#39;voip&#39;): sự kiện call_event (ringring, answer, cancel, endcall)&quot;]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        S6 --&gt; S7[&quot;Điều khiển kết thúc: cancelVoiceCall (cmd 11305) / endVoiceCall (cmd 11306)&quot;]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    end</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    subgraph T2[&quot;Tầng 2: Luồng Truyền Tải Âm Thanh/Hình Ảnh (Media Plane - ZaloRtcSession / Native ZRTC)&quot;]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        M1[&quot;Nhận { rtpServer, rtcpServer, sessId, zrtpKey } từ Tầng 1&quot;] --&gt; M2[&quot;ZaloRtcSession (Pure TS UDP) hoặc ZaloCallController (Native IPC)&quot;]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        M2 --&gt; M3[&quot;Mở kết nối UDP trực tiếp tới rtpServer (IP:Port) &amp; rtcpServer (IP:Port)&quot;]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        M3 --&gt; M4[&quot;Mã hóa gói tin bằng zrtpKey + đóng gói Audio (PCM/Opus) &amp; Video (H.264 payload 97)&quot;]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        M4 --&gt; M5[&quot;Đàm thoại 2 chiều thời gian thực (Full-Duplex Media)&quot;]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    end</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    S3 -.-&gt;|&quot;Bàn giao thông số phiên&quot;| M1</span></span></code></pre></div><h3 id="_1-2-hien-trang-trong-softtynet-zca-js-v2-3-11-—-30-call-apis-pure-typescript-zalortcsession" tabindex="-1">1.2. Hiện trạng trong <code>@softtynet/zca-js</code> (v2.3.11+ — 30 Call APIs &amp; Pure TypeScript <code>ZaloRtcSession</code>) <a class="header-anchor" href="#_1-2-hien-trang-trong-softtynet-zca-js-v2-3-11-—-30-call-apis-pure-typescript-zalortcsession" aria-label="Permalink to &quot;1.2. Hiện trạng trong `@softtynet/zca-js` (v2.3.11+ — 30 Call APIs &amp; Pure TypeScript `ZaloRtcSession`)&quot;">​</a></h3><ul><li><p><strong>Tầng 1 — Complete Signaling Plane (28 APIs trong <code>src/apis/call/</code> + 2 Factory <code>createRtcSession</code>, <code>createController</code>)</strong>:</p><ul><li><strong>14 API Gọi 1-1 (<code>Commands 11300 → 11311, 12006, 12056, 12064</code>, <code>zpw_type = 24</code>)</strong>: <ul><li><code>sendVoiceCall</code> (trọn gói <code>11300</code> + <code>11301</code>), <code>requestVoiceCall</code> (<code>11300</code> — signal <code>401</code>), <code>sendRequestVoiceCall</code> (<code>11301</code> — signal <code>416</code>), <code>ringRingVoiceCall</code> (<code>11302</code> — signal <code>407</code>), <code>answerVoiceCall</code> (<code>11303</code> — signal <code>402</code>), <code>answerAckVoiceCall</code> (<code>11304</code> — signal <code>408</code>), <code>cancelVoiceCall</code> (<code>11305</code> — signal <code>405</code>), <code>endVoiceCall</code> (<code>11306</code> — signal <code>404</code>), <code>holdVoiceCall</code> (<code>11307</code>/<code>11308</code> — signal <code>411</code>/<code>412</code>), <code>unholdVoiceCall</code> (<code>11309</code>/<code>11310</code> — signal <code>413</code>/<code>414</code>), <code>logEndVoiceCall</code> (<code>11311</code> — signal <code>406</code>), <code>updateCallMediaState</code> (<code>12006</code> — <code>/api/voicecall/conf</code>), <code>requestAudioToVideoCall</code> (<code>12056</code>), <code>requestShareScreenCall</code> (<code>12064</code>).</li></ul></li><li><strong>14 API Gọi Nhóm (<code>Group Call Commands 12433 → 12447, 12043, 12044, 12097, 12098</code>, <code>zpw_type = 24</code>)</strong>: <ul><li><code>requestGroupCall</code> (<code>12433</code>), <code>sendRequestGroupCall</code> (<code>12434</code>), <code>addUserGroupCall</code> (<code>12435</code>), <code>answerGroupCall</code> (<code>12436</code>), <code>cancelGroupCall</code> (<code>12437</code>), <code>endGroupCall</code> (<code>12438</code>), <code>ringRingGroupCall</code> (<code>12439</code>), <code>getGroupCallState</code> (<code>12445</code>), <code>finishGroupCall</code> (<code>12446</code>), <code>notifyGroupCall</code> (<code>12447</code>), <code>pingGroupCall</code> (<code>12097</code>), <code>broadcastGroupCallState</code> (<code>12098</code>), <code>joinGroupCall</code> (<code>12043</code>), <code>shareScreenGroupCall</code> (<code>12044</code>).</li><li><strong>Quy ước trạng thái Group Call</strong>: <code>audioState = 0</code> (Mic Bật / Unmuted), <code>audioState = 1</code> (Mic Tắt / Muted); <code>videoState = 0</code> (Camera Bật), <code>videoState = 1</code> (Camera Tắt / Paused).</li></ul></li><li><code>src/realtime/handlers/control.handler.ts</code> &amp; <a href="./api/models.html#callevent"><code>CallEvent</code></a>: Bắt toàn bộ sự kiện <code>call_event</code> thời gian thực qua WebSocket (<code>request</code>, <code>ringring</code>, <code>answer</code>, <code>cancel</code>, <code>endcall</code>, <code>busy</code>, <code>hold</code>, <code>unhold</code>, <code>conf</code>, <code>audio2video</code>, <code>group_request</code>, <code>group_answer</code>, <code>group_broadcast</code>, <code>group_ping</code>...).</li></ul></li><li><p><strong>Tầng 2 — Pure TypeScript Media Engine (<code>src/call-engine/ZaloRtcSession.ts</code>, <code>ZaloSrtpSession.ts</code>, <code>ZRTPPacketCodec.ts</code>) — Đã Kiểm Định Thực Tế 100%</strong>:</p><ul><li><strong>Giao thức UDP <code>ZRTPPacket</code> &amp; <code>SRTP AES-CM-128-HMAC-SHA1-80</code></strong>: <ul><li>Cuộc gọi 1-1: Bắt tay <code>Echo (cmd=248)</code> $\\rightarrow$ <code>InitCall (cmd=1)</code> $\\rightarrow$ <code>RelayPing (cmd=243)</code> / <code>Ping (cmd=2)</code>. Hỗ trợทั้ง Legacy framing (<code>packetMode=1</code>: <code>0x03/0x04/0x05/0x0d/0x0e/0x0f</code>) và Multiplexed ZRTC framing (<code>packetMode=2</code>: <code>0x7f</code> 9-byte header).</li><li>Cuộc gọi nhóm (Zavi SFU): Luôn dùng <code>packetMode=1</code> (5-byte prefix khi gửi, 1-byte <code>0x04</code>/<code>0x0e</code> khi nhận). Bắt tay <code>Echo (cmd=248)</code> $\\rightarrow$ <code>InitZaviPing (cmd=53)</code> $\\rightarrow$ nhận <code>ZaviRoomUpdated (cmd=50)</code>, gửi <code>RequestForward</code> (<code>subCmd=2</code> AudioCodecList, <code>subCmd=11</code> VideoQualityBitrateConfig, <code>subCmd=13</code> VideoQualityRequest) và <code>AudioCodec (cmd=19, codecType=9 khi tắt Mic)</code>.</li></ul></li><li><strong>Đóng gói RTP Video H.264 Annex-B FU-A (<code>0x1c</code>, <code>origNalType=0</code>) &amp; <code>0xBEDE</code> 24-Byte Header Extension</strong>: <ul><li>Sử dụng H.264 Constrained Baseline Profile Level 3.0 (<code>avc1.42001e</code>), các gói lớn (<code>&gt; 1135B</code>) được phân mảnh với <code>fuIndicator = 0x1c</code> (<code>type=28</code>), <code>fuHeader = 0x80</code> (Start) / <code>0x00</code> (Middle) / <code>0x40</code> (End), giữ nguyên Annex-B start code <code>00 00 00 01</code> ở đầu mảnh Start để tương thích với <code>VCMPacket::CopyCodecSpecifics</code> của Zalo Mobile/PC.</li><li>Trong Group Call, mỗi gói RTP Video đính kèm <strong>24-byte RFC 5285 One-Byte Extension (<code>0xBEDE</code>, <code>length=5</code> words)</strong>: <code>0x32</code> (<code>id=3, L=2</code> AbsSendTime) + <code>0x51</code> (<code>id=5, L=1</code> TransportSeq) + <code>0xc2</code> (<code>id=12, L=2</code> VideoGroupCall) + <code>0xd6</code> (<code>id=13, L=6</code> CaptureNtpTime) + <code>0x00</code> (padding).</li><li>Khi nhận RTP Video từ Zavi SFU (<code>SSRC = 1</code>), động cơ tự động đọc <code>CSRC[0]</code> (offset 12..15) để lấy 32-bit VoIP UID của thành viên phát và ánh xạ sang Zalo UID 19 chữ số (<code>frame.partnerId</code>), đồng thời khử trùng lặp gói RTP theo <code>(sequenceNumber, timestamp)</code>.</li></ul></li></ul></li></ul><h3 id="_1-3-ung-dung-thuc-te-cua-bo-api-call-hien-tai" tabindex="-1">1.3. Ứng dụng thực tế của bộ API Call hiện tại <a class="header-anchor" href="#_1-3-ung-dung-thuc-te-cua-bo-api-call-hien-tai" aria-label="Permalink to &quot;1.3. Ứng dụng thực tế của bộ API Call hiện tại&quot;">​</a></h3><ol><li><strong>Nháy máy / Báo thức thông báo (Wake-up / Buzz)</strong>: <ul><li>Khi gửi tin nhắn quan trọng mà khách hàng chưa đọc, gọi <code>api.call.sendVoiceCall(uid, { callType: CallType.Audio })</code> để làm sáng màn hình và đổ chuông điện thoại người nhận trong 5–10 giây, sau đó gọi <code>api.call.cancelVoiceCall(uid, callId)</code>.</li></ul></li><li><strong>Tổng đài thông báo &amp; Tự động phản hồi khi có cuộc gọi đến</strong>: <ul><li>Lắng nghe <code>api.listener.on(&quot;call_event&quot;, ...)</code> để phát hiện ngay khi khách hàng bấm gọi vào tài khoản Zalo: <ul><li>Hiển thị cảnh báo cuộc gọi đến theo thời gian thực trên màn hình CRM/App của nhân viên.</li><li>Hoặc tự động từ chối cuộc gọi (<code>endVoiceCall</code> / <code>cancelVoiceCall</code>) kèm gửi ngay một tin nhắn văn bản hoặc tin nhắn thoại (<code>api.chat.sendVoice</code>) hướng dẫn khách hàng để lại lời nhắn.</li></ul></li></ul></li><li><strong>Giao tiếp giọng nói 2 chiều qua Tin nhắn thoại (<code>sendVoice</code> + <code>voiceToText</code>)</strong>: <ul><li>Nhân viên thu âm trên App/Web và gửi qua <a href="./api/chat.html#sendvoice"><code>api.chat.sendVoice</code></a>, đồng thời dùng <a href="./api/media.html#voicetotext"><code>api.media.voiceToText</code></a> để tự động chuyển tin nhắn thoại của khách thành văn bản.</li></ul></li></ol><h3 id="_1-4-huong-nghien-cuu-tiep-theo-r-d-roadmap-cho-đam-thoai-2-chieu" tabindex="-1">1.4. Hướng nghiên cứu tiếp theo (R&amp;D Roadmap cho Đàm thoại 2 chiều) <a class="header-anchor" href="#_1-4-huong-nghien-cuu-tiep-theo-r-d-roadmap-cho-đam-thoai-2-chieu" aria-label="Permalink to &quot;1.4. Hướng nghiên cứu tiếp theo (R&amp;D Roadmap cho Đàm thoại 2 chiều)&quot;">​</a></h3><p>Khi cần nghiên cứu sâu hơn để giải bài toán truyền âm thanh 2 chiều trong tương lai, các bước R&amp;D cần thực hiện gồm:</p><ol><li><strong>Phân tích cầu nối IPC giữa JS và Native Engine trong Zalo PC (<code>26.7.10</code>)</strong>: <ul><li>Tìm kiếm các lời gọi IPC liên quan đến <code>voip</code>, <code>zrtc</code>, <code>startCall</code>, <code>rtpServer</code>, <code>zrtpKey</code> trong <code>main-dist</code> và <code>pc-dist</code> của <code>/Applications/Zalo.app/Contents/Resources/app.asar</code>.</li></ul></li><li><strong>Phân tích Native Binary trong bộ cài Zalo.app</strong>: <ul><li>Kiểm tra các thư viện động (<code>.node</code>, <code>.dylib</code>, <code>.framework</code>) đi kèm trong <code>/Applications/Zalo.app/Contents/Frameworks</code> để xác định xem Zalo PC nạp module ZRTC qua Electron Node Addon hay Process riêng.</li><li>Nếu là Node Native Addon (<code>.node</code>), có thể nghiên cứu nạp trực tiếp addon đó từ tiến trình Node.js/Electron trên cùng hệ điều hành để đẩy luồng PCM/Opus vào phiên gọi.</li></ul></li><li><strong>Phân tích cấu trúc gói tin UDP RTP/RTCP (<code>Wireshark</code> / <code>tcpdump</code>)</strong>: <ul><li>Bắt gói tin UDP gửi tới <code>rtpServer</code> và <code>rtcpServer</code> trong một cuộc gọi thật trên Zalo PC để đối chiếu header RTP, payload type (Opus / H.264 payload <code>97</code>) và cách <code>zrtpKey</code> được dùng để mã hóa SRTP/ZRTP.</li></ul></li></ol><hr><h2 id="_2-chuyen-đe-2-phan-tich-chay-truc-tiep-tren-react-native-vs-đat-tren-server-gateway" tabindex="-1">2. Chuyên đề 2: Phân tích Chạy Trực Tiếp trên React Native vs Đặt trên Server Gateway <a class="header-anchor" href="#_2-chuyen-đe-2-phan-tich-chay-truc-tiep-tren-react-native-vs-đat-tren-server-gateway" aria-label="Permalink to &quot;2. Chuyên đề 2: Phân tích Chạy Trực Tiếp trên React Native vs Đặt trên Server Gateway&quot;">​</a></h2><h3 id="_2-1-đanh-gia-kha-nang-chay-truc-tiep-softtynet-zca-js-tren-react-native" tabindex="-1">2.1. Đánh giá khả năng chạy trực tiếp <code>@softtynet/zca-js</code> trên React Native <a class="header-anchor" href="#_2-1-đanh-gia-kha-nang-chay-truc-tiep-softtynet-zca-js-tren-react-native" aria-label="Permalink to &quot;2.1. Đánh giá khả năng chạy trực tiếp `@softtynet/zca-js` trên React Native&quot;">​</a></h3><ul><li><strong>Về mặt Giao thức mạng (Network Protocol)</strong>: <ul><li>99% các API của thư viện là mã hóa AES-CBC (<code>crypto-js</code>) + gửi HTTP <code>fetch</code> + nhận sự kiện WebSocket.</li><li>Môi trường React Native <strong>không bị chặn CORS</strong> như trình duyệt Web, nên hoàn toàn gửi được các request tới <code>*.zalo.me</code> từ thiết bị di động.</li></ul></li><li><strong>5 điểm phụ thuộc vào Node.js cần xử lý nếu muốn bundle trực tiếp vào React Native (Metro / Hermes)</strong>:</li></ul><table tabindex="0"><thead><tr><th style="text-align:center;">STT</th><th style="text-align:left;">Module / Thư viện</th><th style="text-align:left;">Vị trí trong Codebase</th><th style="text-align:left;">Vấn đề trên React Native</th><th style="text-align:left;">Hướng xử lý (Khi cần làm bản Universal)</th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td style="text-align:left;"><code>node:fs</code>, <code>node:path</code></td><td style="text-align:left;"><code>src/utils.ts</code>, <code>src/zalo.ts</code>, <a href="./api/auth.html#getqr"><code>api.auth.getQR</code></a></td><td style="text-align:left;">Metro Bundler không có sẵn module <code>node:fs</code> và <code>node:path</code>.</td><td style="text-align:left;">Chuyển sang nạp động (<code>await import(&quot;node:fs&quot;)</code>) chỉ khi truyền đường dẫn file trên Node, còn trên Mobile truyền trực tiếp <code>Uint8Array</code> / <code>ArrayBuffer</code>.</td></tr><tr><td style="text-align:center;">2</td><td style="text-align:left;"><code>ws</code> (Node WebSocket)</td><td style="text-align:left;"><code>src/realtime/listener.ts</code></td><td style="text-align:left;">Gói <code>ws</code> phụ thuộc <code>node:net</code>, <code>node:tls</code>, <code>node:http</code>.</td><td style="text-align:left;">Kiểm tra nếu môi trường có <code>globalThis.WebSocket</code> (React Native hỗ trợ truyền <code>{ headers }</code> ở tham số thứ 3: <code>new WebSocket(url, undefined, { headers })</code>) thì dùng trực tiếp thay cho <code>ws</code>.</td></tr><tr><td style="text-align:center;">3</td><td style="text-align:left;"><code>node:crypto</code> &amp; <code>Buffer</code></td><td style="text-align:left;"><code>src/crypto/ws-cipher.ts</code>, <code>src/crypto/zdb-cipher.ts</code>, <code>src/crypto/zcloud-cipher.ts</code></td><td style="text-align:left;">Giải mã WebSocket (<code>AES-GCM</code>), ZCloud (<code>AES-256-CBC</code>) và ZDB (<code>RSA-2048</code>) đang gọi <code>node:crypto</code> và <code>Buffer</code>.</td><td style="text-align:left;">Chuyển <code>zcloud-cipher</code> sang dùng <code>crypto-js</code> / <code>Uint8Array</code>, và hỗ trợ polyfill <code>react-native-quick-crypto</code> + <code>buffer</code> (hoặc WebCrypto API).</td></tr><tr><td style="text-align:center;">4</td><td style="text-align:left;"><code>form-data</code> (Node Stream)</td><td style="text-align:left;"><a href="./api/media.html#uploadattachment"><code>api.media.uploadAttachment</code></a>, <a href="./api/profile.html#changeaccountavatar"><code>api.profile.changeAccountAvatar</code></a></td><td style="text-align:left;">Dùng Node <code>stream</code> không chạy trên Hermes.</td><td style="text-align:left;">Sử dụng chuẩn <code>FormData</code> / <code>Blob</code> / <code>Uint8Array</code> đa nền tảng.</td></tr><tr><td style="text-align:center;">5</td><td style="text-align:left;">Quản lý Cookie của <code>fetch</code></td><td style="text-align:left;"><code>src/utils.ts</code> (<code>request()</code>)</td><td style="text-align:left;"><code>fetch</code> trên iOS (<code>NSHTTPCookieStorage</code>) và Android (<code>OkHttp</code>) tự động can thiệp vào header <code>Cookie</code>.</td><td style="text-align:left;">Bổ sung <code>credentials: &quot;omit&quot;</code> vào <code>fetch</code> options để <code>tough-cookie</code> kiểm soát hoàn toàn header <code>cookie</code> trên mọi nền tảng.</td></tr></tbody></table><h3 id="_2-2-so-sanh-kien-truc-đat-tren-server-gateway-vs-chay-truc-tiep-tren-app-react-native" tabindex="-1">2.2. So sánh Kiến trúc: Đặt trên Server Gateway vs Chạy trực tiếp trên App React Native <a class="header-anchor" href="#_2-2-so-sanh-kien-truc-đat-tren-server-gateway-vs-chay-truc-tiep-tren-app-react-native" aria-label="Permalink to &quot;2.2. So sánh Kiến trúc: Đặt trên Server Gateway vs Chạy trực tiếp trên App React Native&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Tiêu chí</th><th style="text-align:left;">Phương án 1: Đặt SDK trên Server (Node.js/Bun), App RN gọi qua Server</th><th style="text-align:left;">Phương án 2: Nhúng trực tiếp SDK vào App React Native</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Độ trễ (Latency)</strong></td><td style="text-align:left;">Rất thấp (~15ms – 40ms cho mỗi lệnh API/Signaling). Không gây cảm giác trễ.</td><td style="text-align:left;">Gọi thẳng từ điện thoại tới máy chủ Zalo.</td></tr><tr><td style="text-align:left;"><strong>Giữ kết nối WebSocket (<code>Listener</code>)</strong></td><td style="text-align:left;"><strong>Ổn định 24/7</strong>. Server luôn giữ kết nối nhận tin nhắn ngay cả khi người dùng tắt màn hình điện thoại, sau đó bắn Push Notification (FCM/APNs) về App.</td><td style="text-align:left;">Khi người dùng tắt màn hình hoặc vuốt App xuống Background, iOS/Android sẽ ngắt WebSocket sau ~30 giây.</td></tr><tr><td style="text-align:left;"><strong>Độ ổn định Phiên đăng nhập (<code>Cookie</code> / IP)</strong></td><td style="text-align:left;"><strong>Rất cao</strong>. Phiên <code>API_TYPE = 30</code> (Zalo PC/Web) giữ nguyên 1 địa chỉ IP cố định trên Server.</td><td style="text-align:left;">Khi điện thoại di chuyển đổi từ WiFi sang 4G/5G liên tục, IP của phiên <code>API_TYPE = 30</code> thay đổi liên tục.</td></tr><tr><td style="text-align:left;"><strong>Đồng bộ nhiều nhân viên (Multi-Agent CRM)</strong></td><td style="text-align:left;">Nhiều máy điện thoại / trình duyệt cùng thao tác trên 1 tài khoản Zalo thông qua Server mà không bị đá văng phiên của nhau.</td><td style="text-align:left;">Mỗi máy tự giữ kết nối riêng (chỉ có 1 kết nối WebSocket <code>enable_encrypt</code> hoạt động tại 1 thời điểm trên cùng <code>API_TYPE = 30</code>).</td></tr><tr><td style="text-align:left;"><strong>Chi phí hạ tầng Server</strong></td><td style="text-align:left;">Cần Server duy trì kết nối và băng thông nếu tải nhiều file lớn.</td><td style="text-align:left;">Tận dụng trực tiếp mạng 4G/WiFi và IP của từng máy điện thoại người dùng.</td></tr></tbody></table><blockquote><p><strong>Kết luận kiến trúc</strong>:</p><ul><li>Nếu làm <strong>Hệ thống quản lý tập trung / CRM / Chatbot / Nhận tin nhắn ngầm 24/7 có Push Notification</strong>: Nên đặt <code>@softtynet/zca-js</code> trên <strong>Server Node.js/Bun</strong> (Phương án 1).</li><li>Nếu làm <strong>Công cụ chạy theo phiên khi người dùng mở App (Foreground Utility)</strong> để tận dụng IP của chính điện thoại người dùng: Có thể nâng cấp lớp Adapter để chạy trực tiếp trên <strong>React Native</strong> (Phương án 2).</li></ul></blockquote><hr><h2 id="_3-chuyen-đe-3-kien-truc-phan-quyen-danh-sach-thanh-vien-nhom-cong-đong-lockviewmember" tabindex="-1">3. Chuyên đề 3: Kiến trúc Phân quyền Danh sách Thành viên Nhóm &amp; Cộng đồng (<code>lockViewMember</code>) <a class="header-anchor" href="#_3-chuyen-đe-3-kien-truc-phan-quyen-danh-sach-thanh-vien-nhom-cong-đong-lockviewmember" aria-label="Permalink to &quot;3. Chuyên đề 3: Kiến trúc Phân quyền Danh sách Thành viên Nhóm &amp; Cộng đồng (`lockViewMember`)&quot;">​</a></h2><h3 id="_3-1-cac-endpoint-thong-tin-nhom-trong-zalo-pc-26-7-10" tabindex="-1">3.1. Các Endpoint Thông tin Nhóm trong Zalo PC (<code>26.7.10</code>) <a class="header-anchor" href="#_3-1-cac-endpoint-thong-tin-nhom-trong-zalo-pc-26-7-10" aria-label="Permalink to &quot;3.1. Các Endpoint Thông tin Nhóm trong Zalo PC (`26.7.10`)&quot;">​</a></h3><p>Trong mã nguồn Zalo PC hiện có 4 endpoint truy vấn thông tin và thành viên nhóm:</p><ol><li><a href="./api/group.html#getgroupinfo"><code>getGroupInfo</code></a> (<code>/api/group/getmg-v2</code> — <code>cmd 12028</code>): <ul><li>Nhận <code>gridVerMap: { [groupId]: 0 }</code>.</li><li>Trả về <code>gridInfoMap[groupId]</code> chứa <code>memVerList</code> (<code>[&quot;&lt;uid&gt;_&lt;ver&gt;&quot;, ...]</code>), <code>adminIds</code>, <code>creatorId</code>, <code>totalMember</code>, <code>setting</code>.</li></ul></li><li><a href="./api/group.html#getgrouplinkinfo"><code>getGroupLinkInfo</code></a> (<code>/api/group/link/ginfo</code> — <code>cmd 11824</code>): <ul><li>Nhận <code>{ link, avatar_size: 120, member_avatar_size: 120, mpage }</code>.</li><li>Trả về <code>currentMems</code> (phân trang theo <code>mpage</code>), <code>hasMoreMember</code>, <code>adminIds</code>, <code>creatorId</code>, <code>totalMember</code>, <code>setting</code>.</li></ul></li><li><code>getGroupInfos</code> (<code>/api/group/getmg</code> — <code>cmd 12604</code>): <ul><li>Nhận <code>{ grids, avatar_size: 120, member_avatar_size: 120, mpage, mcount }</code>.</li></ul></li><li><a href="./api/group.html#getgroupinfov2"><code>getGroupInfoV2</code></a> (<code>/api/group/getgi/v2</code> &amp; <code>/api/group/getgi</code> — <code>cmd 11162</code>): <ul><li>Nhận <code>{ grid, avatar_size: 120, member_avatar_size: 120, mpage, mcount: 100 }</code>.</li></ul></li></ol><h3 id="_3-2-co-che-kiem-soat-setting-lockviewmember-tai-backend-zalo" tabindex="-1">3.2. Cơ chế kiểm soát <code>setting.lockViewMember</code> tại Backend Zalo <a class="header-anchor" href="#_3-2-co-che-kiem-soat-setting-lockviewmember-tai-backend-zalo" aria-label="Permalink to &quot;3.2. Cơ chế kiểm soát `setting.lockViewMember` tại Backend Zalo&quot;">​</a></h3><ul><li><strong>Khi <code>setting.lockViewMember === 0</code> (Nhóm thông thường hoặc Cộng đồng không khóa danh sách thành viên)</strong>: <ul><li><code>getGroupInfo</code> trả về toàn bộ danh sách <code>memVerList</code>.</li><li><code>getGroupLinkInfo</code> cho phép phân trang qua tham số <code>memberPage</code> (<code>mpage = 1, 2, 3...</code>) cho đến khi <code>hasMoreMember === 0</code>.</li></ul></li><li><strong>Khi <code>setting.lockViewMember === 1</code> (Cộng đồng bật <em>&quot;Chỉ trưởng/phó cộng đồng được xem danh sách thành viên&quot;</em>)</strong>: <ul><li>Máy chủ Zalo kiểm tra <code>uid</code> của phiên gọi API: <ul><li>Nếu <code>uid</code> là <strong>Trưởng nhóm (<code>creatorId</code>)</strong> hoặc <strong>Phó nhóm (<code>adminIds</code>)</strong>: Server trả về đầy đủ 100% danh sách thành viên trong <code>memVerList</code> / <code>currentMems</code>.</li><li>Nếu <code>uid</code> là <strong>Thành viên thường</strong>: Server lọc danh sách ngay tại tầng Backend, chỉ trả về ID của ban quản trị (<code>creatorId</code>, <code>adminIds</code>) và chính <code>uid</code> đang gọi API.</li></ul></li></ul></li></ul><h3 id="_3-3-cau-truc-cac-api-du-lieu-hoat-đong-trong-nhom-co-san-trong-sdk" tabindex="-1">3.3. Cấu trúc các API dữ liệu hoạt động trong nhóm có sẵn trong SDK <a class="header-anchor" href="#_3-3-cau-truc-cac-api-du-lieu-hoat-đong-trong-nhom-co-san-trong-sdk" aria-label="Permalink to &quot;3.3. Cấu trúc các API dữ liệu hoạt động trong nhóm có sẵn trong SDK&quot;">​</a></h3><p>Các dữ liệu tương tác phát sinh bên trong nhóm được quản lý qua các phân hệ độc lập trong SDK:</p><ul><li><strong>Lịch sử tin nhắn &amp; Sự kiện nhóm</strong>: <a href="./api/group.html#getgroupchathistory"><code>api.group.getGroupChatHistory</code></a> (<code>/api/cm/getrecentv2</code>) và <a href="./api/group.html#getgroupcloudmessagejump"><code>api.group.getGroupCloudMessageJump</code></a> (<code>/api/cm/getjumpv2</code> — <code>cmd 12508</code>).</li><li><strong>Kho lưu trữ Media / File / Link của nhóm</strong>: <a href="./api/media.html#getconversationmedia"><code>api.media.getConversationMedia</code></a> (<code>/api/mediastore/list</code> — <code>cmd 11841</code>, hỗ trợ <code>mediaType: &quot;media&quot; | &quot;file&quot; | &quot;link&quot;</code>).</li><li><strong>Bảng tin nhóm (Ghi chú, Bình chọn, Nhắc hẹn)</strong>: <ul><li><a href="./api/board.html#getlistboard"><code>api.board.getListBoard</code></a> (<code>/api/board/list</code> — <code>cmd 12140</code>)</li><li><a href="./api/board.html#getpolldetail"><code>api.board.getPollDetail</code></a> (<code>/api/poll/detail</code> — <code>cmd 12081</code>)</li><li><a href="./api/board.html#getreminderresponses"><code>api.board.getReminderResponses</code></a> (<code>/api/board/topic/listResponseEvent</code>)</li></ul></li><li><strong>Tra cứu hồ sơ thành viên theo danh sách UID</strong>: <a href="./api/group.html#getgroupmembersinfo"><code>api.group.getGroupMembersInfo</code></a> (<code>/api/social/group/members</code>).</li></ul>',32)])])}const p=t(i,[["render",d]]);export{u as __pageData,p as default};
